package main

import (
	"strings"
	"testing"
)

// La prueba del paso 3.4: la R que sale de nuestra tabla tiene que ser el MISMO texto que escribio
// aapt2 con `link --java` sobre el proyecto del studio (493 bytes, docs/evidencia.md 31).

const rDeAapt2 = `/* AUTO-GENERATED FILE. DO NOT MODIFY.
 *
 * This class was automatically generated by the
 * aapt tool from the resource data it found. It
 * should not be modified by hand.
 */

package com.hola.apkcstudio;

public final class R {
  public static final class id {
    public static final int pulsar=0x7f010000;
  }
  public static final class layout {
    public static final int main=0x7f020000;
  }
  public static final class style {
    public static final int AppTheme=0x7f030000;
  }
}`

func TestRLaMismaQueAapt2(t *testing.T) {
	salida, err := rDeTabla(tablaDelStudio())
	if err != nil {
		t.Fatal(err)
	}
	if len(rDeAapt2) != 493 {
		t.Fatalf("el texto fijado de aapt2 mide %d bytes, no 493", len(rDeAapt2))
	}
	if salida != rDeAapt2 {
		t.Errorf("la R no casa byte a byte:\n--- nuestro ---\n%s\n--- aapt2 ---\n%s", salida, rDeAapt2)
	}
	if strings.HasSuffix(salida, "\n") {
		t.Error("el fichero termina con salto de linea, y el de aapt2 termina en la llave")
	}
}

func TestRDesfiguraNombresYOrdena(t *testing.T) {
	// medido sobre la variante D del parrafo 31: la cadena "con-guion.y.punto" sale
	// "con_guion_y_punto" con el id 0x7f060000, y las tres van en orden alfabetico por el nombre del
	// fuente. El tipo string es el sexto, como en la variante medida.
	tabla := tablaEscribir{
		idPaquete:     0x7f,
		nombrePaquete: "com.hola.apkcstudio",
		nombresTipo:   []string{"attr", "bool", "color", "id", "layout", "string"},
		claves:        []string{"normal", "con-guion.y.punto", "str_simple"},
		tipos: []tipoEscribir{
			{id: 6, specFlags: []uint32{0}, bloques: []bloqueEscribir{{entradas: []entradaEscribir{
				{clave: 1, valor: valorEscribir{tipo: tipoCadena}},
				{clave: 0, valor: valorEscribir{tipo: tipoCadena}},
				{clave: 2, valor: valorEscribir{tipo: tipoCadena}},
			}}}},
		},
	}
	salida, err := rDeTabla(tabla)
	if err != nil {
		t.Fatal(err)
	}
	for _, queramos := range []string{
		"public static final class string {",
		"public static final int con_guion_y_punto=0x7f060000;",
		"public static final int normal=0x7f060001;",
		"public static final int str_simple=0x7f060002;",
	} {
		if !strings.Contains(salida, queramos) {
			t.Errorf("falta %q en:\n%s", queramos, salida)
		}
	}
}

func TestRRechaza(t *testing.T) {
	base := tablaDelStudio()

	malo := tablaDelStudio()
	malo.tipos[2].bloques[0].entradas[0].clave = len(malo.claves)
	if _, err := rDeTabla(malo); err == nil {
		t.Error("una entrada con clave inexistente fue aceptada")
	}

	malo = tablaDelStudio()
	malo.nombresTipo = []string{"id", "layout"} // el tipo 3 se queda sin nombre
	malo.tipos[2].id = 3
	if _, err := rDeTabla(malo); err == nil {
		t.Error("un tipo sin nombre en la tabla fue aceptado")
	}

	// entradas sin ordenar por nombre: el id depende del lugar, y aapt2 las ordena
	malo = tablaEscribir{
		idPaquete: 0x7f, nombrePaquete: "p",
		nombresTipo: []string{"string"},
		claves:      []string{"b", "a"},
		tipos: []tipoEscribir{{id: 1, bloques: []bloqueEscribir{{entradas: []entradaEscribir{
			{clave: 0}, {clave: 1},
		}}}}},
	}
	// la primera entrada nombra "b" y la segunda "a": al reves del orden con que aapt2 emite, que es
	// el que decide los ids
	if _, err := rDeTabla(malo); err == nil {
		t.Error("un tipo con las entradas fuera de orden fue aceptado")
	}

	// dos nombres que al desfigurarlos dan el mismo identificador
	malo = tablaEscribir{
		idPaquete: 0x7f, nombrePaquete: "p",
		nombresTipo: []string{"string"},
		claves:      []string{"con-guion", "con_guion"},
		tipos: []tipoEscribir{{id: 1, bloques: []bloqueEscribir{{entradas: []entradaEscribir{
			{clave: 0}, {clave: 1},
		}}}}},
	}
	if _, err := rDeTabla(malo); err == nil {
		t.Error("dos nombres que chocan al desfigurarlos fueron aceptados")
	}

	if _, err := rDeTabla(base); err != nil {
		t.Errorf("la tabla valida fue rechazada: %v", err)
	}
}
